-- 010 — Colegios (directorio oficial, 12.038 vigentes) + Admisión + retira Empresas.
-- Fuente: MINEDUC vía chile-hub (CC BY, con atribución). RBD como clave.

create table if not exists colegios (
  rbd text primary key,
  dv text not null default '',
  nombre text not null,
  dependencia text not null default '',
  region smallint not null references regiones(codigo),
  comuna text not null references comunas(codigo),
  latitud double precision,
  longitud double precision,
  estado text not null default 'Vigente',
  creado_en timestamptz not null default now()
);
comment on table colegios is 'Directorio oficial de establecimientos (RBD)';
create index if not exists idx_colegios_region on colegios (region);
create index if not exists idx_colegios_comuna on colegios (comuna);
create index if not exists idx_colegios_nombre on colegios (nombre);
alter table colegios enable row level security;
revoke all on colegios from public;
grant select on colegios to public;

