create or replace function sembrar_datos_demo() returns void language plpgsql security definer set search_path = public as $$
declare v_ada uuid; v_alan uuid; v_grace uuid; v_linus uuid; v_marie uuid;
begin
  if (select count(*) from personas) > 0 then return; end if;
  select id into v_ada from personas where correo = 'ada@acme.com';
  select id into v_alan from personas where correo = 'alan@globex.io';
  select id into v_grace from personas where correo = 'grace@initech.dev';
  select id into v_linus from personas where correo = 'linus@hooli.com';
  select id into v_marie from personas where correo = 'marie@umbrella.salud';
end; $$;

create or replace function eliminar_colegio(p_rbd text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if coalesce(btrim(p_rbd), '') = '' then
    raise exception 'El RBD del colegio es obligatorio.' using errcode = 'P0001';
  end if;
  delete from colegios where rbd = btrim(p_rbd);
  if not found then
    raise exception 'Colegio no encontrado.' using errcode = 'P0002';
  end if;
  return true;
end;
$$;

grant execute on function eliminar_colegio(text) to public;
